@startuml

class Gym {
  + computeOverallBalance(month : date) : int
  + computeOverallBalance(year : int) : int
  + sendRemindersForArrears()
  + sendRemindersForMonthlyChecks()
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class WorkoutPlan {
  + weeklyVisits : int
}

class Exercise {
  + description : string
  + repetitions : int
  + frequency : string
}

class MedicalCheckResult {
  + weight : double
  + bodyFat : double
  + electrocardiogram : string
  + restingHeartbeats : int
  + stressHeartbeats : int
}

abstract class Subscription {
}

class MonthlySubscription extends Subscription {
}

class AnnualSubscription extends Subscription {
}

abstract class Service {
  + name : string
  + additionalCost : float
}

class BaseService extends Service {
}

class AdditionalService extends Service {
}

Customer "1" -- "1" Gym : belongs to
Customer "1" -- "1" Subscription : has
Customer "1" -- "0..1" WorkoutPlan : associated with
Customer "1" -- "0..*" MedicalCheckResult : undergoes
Subscription "1" -- "1..*" Service : includes
WorkoutPlan "1" -- "1..*" Exercise : defines
Gym "1" -- "0..*" MedicalCheckResult : archives

@enduml

